{
  "narrative_summary": "Self Serve Funnel produced the best outcome in 41% of runs of this model. The link from Customer Acquisition Cost to New Revenue is a fragility worth checking before acting.",
  "story_headlines": {
    "opt_selfserve": "Self Serve Funnel produced the best outcome where acquisition cost stays contained relative to revenue gained.",
    "opt_paid": "Paid Acquisition would need a lower acquisition cost to produce the best outcome instead.",
    "opt_partner": "Partner Channel would need materially stronger modelled revenue to produce the best outcome instead.",
    "opt_outbound": "Outbound Sales would need a substantially improved cost to revenue relationship to lead the comparison."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 64% of variations, a moderate but not high level of stability.",
    "primary_risk": "The link from Customer Acquisition Cost to New Revenue could flip which option this model points to.",
    "stability_factors": [
      "Self Serve Funnel keeps a modelled outcome advantage across most sampled variations"
    ],
    "fragility_factors": [
      "The link from Customer Acquisition Cost to New Revenue is the main source of movement in the ordering"
    ]
  },
  "readiness_rationale": "The comparison is settled enough to act on, though Customer Acquisition Cost is not yet evidence-backed and is worth firming up before committing budget.",
  "evidence_enhancements": {
    "fac_cac": {
      "specific_action": "Pull actual blended acquisition cost from the last two quarters of finance and marketing data rather than relying on the modelled estimate.",
      "rationale": "This relationship is the main source of movement in which option this model points to.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the current acquisition cost yourself before checking the actual figure."
    }
  },
  "scenario_contexts": {
    "edge_cac_growth": {
      "trigger_description": "If Customer Acquisition Cost rises well beyond current modelled levels while New Revenue does not scale with it...",
      "consequence": "...then this model points to Paid Acquisition rather than Self Serve Funnel."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_cac",
      "factor_label": "Customer Acquisition Cost",
      "current_display": "420 GBP",
      "flip_display": "610 GBP",
      "narrative": "If Customer Acquisition Cost moves from 420 GBP to 610 GBP, this model points to a different option."
    }
  ],
  "bias_findings": [],
  "key_assumptions": [
    "The link from Customer Acquisition Cost to New Revenue assumes current cost levels persist through next quarter.",
    "The comparison assumes all four bets are modelled on comparable time horizons for realising New Revenue."
  ],
  "decision_quality_prompts": [
    {
      "question": "This failed because Customer Acquisition Cost rose well past modelled levels. What early signal would have shown that coming?",
      "principle": "Pre-mortem (Klein)",
      "applies_because": "The comparison is settled enough to act on, but the main fragility sits in a factor that has not yet been evidence-checked."
    },
    {
      "question": "What would make you switch from Self Serve Funnel to Paid Acquisition?",
      "principle": "Consider-the-opposite",
      "applies_because": "Self Serve Funnel's own share is well below a level where switching away would be surprising, so naming the switching condition sharpens the choice."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Budget went to Self Serve Funnel, but Customer Acquisition Cost climbed well past modelled levels and New Revenue failed to scale with it.",
    "warning_signs": [
      "Acquisition cost per new customer trending upward month over month",
      "New Revenue growth flattening despite steady spend"
    ],
    "mitigation": "Track actual acquisition cost weekly against the modelled level and set a review point if it climbs materially.",
    "grounded_in": ["edge_cac_growth", "fac_cac"],
    "review_trigger": "Reconvene if acquisition cost climbs well past modelled levels before next planning cycle."
  }
}
